<script setup lang="ts">
import { computed, onMounted, shallowRef, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { fetchEquipment, facilityNames } from '../../api/equipment'
import { useBusinessRead } from '../../composables/useBusinessRead'
import { fetchCatalog } from '../../api/account'
const route = useRoute(), router = useRouter(), keyword = shallowRef(String(route.query.keyword ?? '')), enabled = shallowRef(String(route.query.enabled ?? '')), facilityType = shallowRef(String(route.query.facilityType ?? ''))
const buildingId = shallowRef(String(route.query.buildingId ?? '')), floorId = shallowRef(String(route.query.floorId ?? '')), locationId = shallowRef(String(route.query.locationId ?? ''))
const { data: catalog, message: catalogMessage, load: loadCatalog } = useBusinessRead(fetchCatalog)
const floors = computed(() => catalog.value?.floors.filter(f => !buildingId.value || f.buildingId === buildingId.value) ?? []), locations = computed(() => catalog.value?.locations.filter(l => l.reportable && (!floorId.value || l.floorId === floorId.value) && floors.value.some(f => f.id === l.floorId)) ?? [])
const { data, loading, message, stale, lastSuccessAt, clear, load } = useBusinessRead(() => fetchEquipment({ page: Math.max(1, Number(route.query.page ?? 1) || 1), pageSize: 20, keyword: String(route.query.keyword ?? ''), enabled: route.query.enabled === 'true' ? true : route.query.enabled === 'false' ? false : undefined, facilityType: String(route.query.facilityType ?? ''), buildingId: String(route.query.buildingId ?? ''), floorId: String(route.query.floorId ?? ''), locationId: String(route.query.locationId ?? '') }))
function apply(page = 1) { void router.replace({ path: '/equipment', query: { keyword: keyword.value, enabled: enabled.value, facilityType: facilityType.value, buildingId: buildingId.value, floorId: floorId.value, locationId: locationId.value, page: String(page) } }) }
onMounted(() => { void loadCatalog() })
watch(() => route.fullPath, () => { clear(); void load() }, { immediate: true })
</script>
<template><div class="page-heading"><div><h1>设备台账</h1><p class="muted">维护设备资料和独立启停用，工单历史保留。</p></div><RouterLink class="primary link-button" to="/equipment/new">补录范围内设备</RouterLink></div><section class="card"><form @submit.prevent="apply()"><div class="form-grid"><label>搜索编号／名称／台账地址<input v-model="keyword" maxlength="100"></label><label>楼栋<select v-model="buildingId" @change="floorId = ''; locationId = ''"><option value="">全部楼栋</option><option v-for="b in catalog?.buildings" :key="b.id" :value="b.id">{{ b.name }}</option></select></label><label>楼层<select v-model="floorId" @change="locationId = ''"><option value="">全部楼层</option><option v-for="f in floors" :key="f.id" :value="f.id">{{ f.name }}</option></select></label><label>位置<select v-model="locationId"><option value="">全部范围内位置</option><option v-for="l in locations" :key="l.id" :value="l.id">{{ l.name }}</option></select></label><label>设备状态<select v-model="enabled"><option value="">全部</option><option value="true">启用</option><option value="false">停用</option></select></label><label>设施类型<select v-model="facilityType"><option value="">全部</option><option v-for="(name, type) in facilityNames" :key="type" :value="type">{{ name }}</option></select></label></div><div class="actions"><button class="primary" :disabled="loading">应用筛选</button><button type="button" class="secondary" :disabled="loading" @click="load">刷新</button></div></form><p v-if="catalogMessage" class="notice">{{ catalogMessage }} <button class="text-button" @click="loadCatalog">重试位置目录</button></p><p v-if="loading" role="status">正在读取台账…</p><p v-if="message" class="notice" role="alert">{{ message }} {{ stale ? `上次成功 ${lastSuccessAt}，资料可能过期。` : '' }}</p><p v-if="data && !data.records.length" class="muted">没有符合条件的设备。</p><ul v-if="data" class="business-list"><li v-for="e in data.records" :key="e.id"><RouterLink :to="{ path: `/equipment/${e.id}`, query: { returnTo: route.fullPath } }"><strong>{{ e.equipmentNo }} · {{ e.name }}</strong><span>{{ e.enabled ? '启用' : '停用' }} · {{ facilityNames[e.facilityType] }} · {{ e.addressText }}</span><small>{{ e.currentWorkOrder ? `有未完结工单 ${e.currentWorkOrder.workOrderNo}，禁止移动` : '无未完结工单' }}</small></RouterLink></li></ul><div v-if="data" class="actions"><span>共{{ data.total }}项</span><button class="secondary" :disabled="loading || data.page <= 1" @click="apply(data.page - 1)">上一页</button><span>第{{ data.page }}页</span><button class="secondary" :disabled="loading || data.page * data.pageSize >= data.total" @click="apply(data.page + 1)">下一页</button></div></section></template>
